import pytest


def test_rescale_to_unit():
    assert rescale_to_unit([1.0, 2.0, 3.0]) == pytest.approx(
        [0.0, 0.5, 1.0]
    )
    assert rescale_to_unit([-5.0, 0.0, 5.0]) == pytest.approx(
        [0.0, 0.5, 1.0]
    )
    assert rescale_to_unit([10.0, 0.0, 5.0]) == pytest.approx(
        [1.0, 0.0, 0.5]
    )
    assert rescale_to_unit([2.0, 4.0]) == pytest.approx(
        [0.0, 1.0]
    )
